import fs from 'fs';
import { parse } from 'csv-parse/sync';
import * as XLSX from 'xlsx';

export class DataProvider {
  /**
   * Reads and parses a JSON test data file.
   * @param filePath - Path to the JSON file.
   * @returns Parsed JSON data.
   */
  static readJson(filePath: string) {
    const data = fs.readFileSync(filePath, 'utf8');
    return JSON.parse(data);
  }

  /**
   * Reads a CSV test data file, using the header row as object keys.
   * @param filePath - Path to the CSV file.
   * @returns Array of row objects.
   */
  static readCsv(filePath: string) {
    const data = fs.readFileSync(filePath);
    return parse(data, {
      columns: true,
      skip_empty_lines: true,
    });
  }

  /**
   * Reads the first worksheet of an Excel file.
   * @param filePath - Path to the Excel file.
   * @returns Array of rows, each row being an array of cell values.
   */
  static readExcel(filePath: string) {
    const workbook = XLSX.readFile(filePath);
    const sheetName = workbook.SheetNames[0];
    const worksheet = workbook.Sheets[sheetName];
    return XLSX.utils.sheet_to_json(worksheet, { header: 1 });
  }
}
